-- ===== Muhammad al-Xorazmiy =====
UPDATE quiz_questions SET question_ru = 'Откуда произошло слово «алгоритм»?', options_ru = '["От греческого слова «арифмос»", "От латинской формы имени аль-Хорезми", "От арабского слова «аль-джабр»", "От латинского слова «алго»"]'::jsonb, explanation_ru = 'Имя аль-Хорезми на латыни писалось как «Algoritmi», отсюда и произошёл термин «алгоритм».' WHERE id = 124;
