UPDATE quiz_questions SET question_ru = 'По какой причине учёного назвали аль-Хорезми?', options_ru = '["За то, что родился в Хорезмском краю", "За то, что правил в Хорезме", "За то, что построил обсерваторию в Хорезме", "За то, что написал труд под названием «Хорезм»"]'::jsonb, explanation_ru = 'Учёного назвали аль-Хорезми за то, что он родился в Хорезмском краю; большая часть его жизни прошла в багдадском «Байт уль-хикма». Источник: Национальная энциклопедия Узбекистана.' WHERE id = 1967;
