UPDATE quiz_questions SET question_ru = 'От названия какого труда аль-Хорезми произошёл термин «алгебра»?', options_ru = '["«Китаб сурат аль-ард»", "«Осор уль-бокия»", "«Аль-китаб аль-мухтасар фи хисаб аль-джабр ва-ль-мукабала»", "«Основы астрономии»"]'::jsonb, explanation_ru = 'Термин «алгебра» произошёл от слова «аль-джабр» в названии труда «Аль-китаб аль-мухтасар фи хисаб аль-джабр ва-ль-мукабала». Источник: ЮНЕСКО, «History of Civilizations of Central Asia».' WHERE id = 1969;
UPDATE quiz_questions SET question_ru = 'В какой форме имя аль-Хорезми было передано на латынь?', options_ru = '["«Alfraganus»", "«Avicenna»", "«Algebra»", "«Algoritmi»"]'::jsonb, explanation_ru = 'Имя аль-Хорезми было передано на латынь в форме «Algoritmi». Источник: Национальная энциклопедия Узбекистана.' WHERE id = 1970;
UPDATE quiz_questions SET question_ru = 'Как сегодня называется последовательность правил вычисления благодаря латинской форме имени аль-Хорезми?', options_ru = '["Алгоритм", "Алгебра", "Геометрия", "Тригонометрия"]'::jsonb, explanation_ru = 'Оттого что имя аль-Хорезми было передано на латынь в форме «Algoritmi», последовательность правил вычисления сегодня называют «алгоритмом». Источник: Национальная энциклопедия Узбекистана.' WHERE id = 1971;
UPDATE quiz_questions SET question_ru = 'Какие цифры и какую систему счисления объяснил аль-Хорезми?', options_ru = '["Римские цифры и двенадцатеричную систему", "Индийские цифры и десятичную систему счисления", "Греческие цифры и шестидесятеричную систему", "Египетские цифры и пятеричную систему"]'::jsonb, explanation_ru = 'Аль-Хорезми объяснил индийские цифры и десятичную систему счисления, в том числе ноль. Источник: ЮНЕСКО, «History of Civilizations of Central Asia».' WHERE id = 1972;
UPDATE quiz_questions SET question_ru = 'Под каким именем известны сегодня индийские цифры, объяснённые аль-Хорезми?', options_ru = '["«Римские цифры»", "«Греческие цифры»", "«Арабские цифры»", "«Латинские цифры»"]'::jsonb, explanation_ru = 'Через труд аль-Хорезми индийские цифры распространились в Европе, и сегодня их называют «арабскими цифрами». Источник: ЮНЕСКО, «History of Civilizations of Central Asia».' WHERE id = 1973;
UPDATE quiz_questions SET question_ru = 'Что приведено в труде аль-Хорезми «Китаб сурат аль-ард»?', options_ru = '["Список звёзд", "Праздники народов", "Описание лекарственных растений", "Координаты городов и рек"]'::jsonb, explanation_ru = 'В труде «Китаб сурат аль-ард» приведены координаты известных в то время городов и рек. Источник: Национальная энциклопедия Узбекистана.' WHERE id = 1974;
